#include <iostream>

using std::cout;
using std::endl;

int main()
{
    const int iCoefficientToStrength = 0x00000001;
    const int iCoefficientToDefense = 0x00000002;
    const int iCoefficientToSpeed = 0x00000004;

    int iBuff = iCoefficientToStrength | iCoefficientToSpeed;

    cout << "Strength : " << (iBuff & iCoefficientToStrength) << endl;
    cout << "Defense : " << (iBuff & iCoefficientToDefense) << endl;
    cout << "Speed : " << (iBuff & iCoefficientToSpeed) << endl << endl;

    iBuff ^= iCoefficientToSpeed;

    cout << "Strength : " << (iBuff & iCoefficientToStrength) << endl;
    cout << "Defense : " << (iBuff & iCoefficientToDefense) << endl;
    cout << "Speed : " << (iBuff & iCoefficientToSpeed) << endl;

    return 0;
}
